from lib import *
r=[]
r.append(R(6887150,"सी बास प्रोवेंसल","सी बास भूमध्यसागर में पाई जाने वाली दृढ़ लेकिन नाज़ुक सफ़ेद मछली है। इसे आमतौर पर टमाटर और सब्ज़ियों की सॉस में पकाया जाता है। इसे रोस्टेड आलू और साइड सलाद के साथ परोसें।","8","4 औंस मछली + 2 बड़े चम्मच सॉस",
["2 पाउंड सी बास","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1 बड़ा चम्मच जैतून का तेल","1 मध्यम प्याज़ (कटा हुआ)","1 मध्यम लाल शिमला मिर्च (पतली कटी हुई)","2 फाँक लहसुन (पतला कटा हुआ)","1 (15 औंस) डिब्बा कटे हुए टमाटर","1 बड़ा चम्मच टमाटर का पेस्ट","1/4 छोटा चम्मच कुटी हुई लाल मिर्च के गुच्छे","1/4 कप काले ज़ैतून","2 छोटे चम्मच केपर्स","1/2 कप ताज़ी तुलसी (कटी हुई)"],
["फ़िलेट पर नमक और काली मिर्च छिड़कें। एक बड़ी नॉनस्टिक कड़ाही में मध्यम-तेज़ आँच पर जैतून का तेल गरम करें। फ़िलेट डालें और हर तरफ़ लगभग 4 मिनट या पूरी तरह पकने तक सेकें। मछली को कड़ाही से निकालकर प्लेट में रखें। गरम रखने के लिए हल्का सा ढक दें।","कड़ाही में प्याज़ और लाल शिमला मिर्च डालें और नरम होने तक 5 मिनट भूनें। लहसुन डालें और 1 मिनट भूनें। बिना निथारे टमाटर, टमाटर का पेस्ट और लाल मिर्च के गुच्छे डालें और उबाल आने दें। आँच धीमी करें और सॉस के गाढ़ा होने तक 5 से 8 मिनट पकाएँ। ज़ैतून और केपर्स डालें और 1 मिनट पकाएँ।","सी बास को सॉस के साथ परोसें और ऊपर से तुलसी छिड़कें।"]))
r.append(R(6887659,"रोस्टेड शिमला मिर्च और सफ़ेद बीन्स डिप","यह रोस्टेड शिमला मिर्च और सफ़ेद बीन्स डिप एक स्वादिष्ट और मलाईदार स्टार्टर है जो रोस्टेड मिर्च की धुएँदार महक को सफ़ेद बीन्स के हल्के स्वाद के साथ मिलाता है। यह आपके स्टार्टर्स की थाली में बढ़िया इजाफ़ा है या विभिन्न स्नैक्स के साथ स्वादिष्ट डिप के रूप में परोसा जा सकता है।","6","1/3 कप",
["1 (15 औंस) डिब्बा कैनेलिनी बीन्स (पानी निथारा और धोया हुआ)","1 (8 औंस) जार रोस्टेड लाल शिमला मिर्च (कटी हुई, तरल अलग रखें)","2 बड़े चम्मच जैतून का तेल","2 फाँक लहसुन (बारीक कटा हुआ)","1 बड़ा चम्मच नीबू का रस","1 छोटा चम्मच पिसा जीरा","1/2 छोटा चम्मच स्मोक्ड पेपरिका","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1 बड़ा चम्मच पानी (ज़रूरत के अनुसार)"],
["फ़ूड प्रोसेसर में सफ़ेद बीन्स, रोस्टेड और कटी हुई लाल शिमला मिर्च, जैतून का तेल, बारीक कटा लहसुन, ताज़ा नीबू का रस, पिसा जीरा, स्मोक्ड पेपरिका, नमक और काली मिर्च डालें।","मिश्रण को तब तक पल्स करें जब तक वह टूटना शुरू न हो जाए। फ़ूड प्रोसेसर चलते हुए, रोस्टेड लाल शिमला मिर्च का रस धीरे-धीरे डालें, जब तक कि मिश्रण चिकना और मलाईदार न हो जाए। आपको प्रोसेसर को एक-दो बार रोककर किनारों से मिश्रण खुरचना पड़ सकता है।"]))
r.append(R(6888570,"ब्रोकली और बादाम सलाद","पेश है हमारा ब्रोकली और बादाम सलाद, बनावट और स्वाद का ऐसा मेल जो आपकी इंद्रियों को तरोताज़ा कर देता है। कुरकुरी ब्रोकली, कुरकुरे बादाम, तीखे प्याज़ और स्वादिष्ट घर पर बनी ड्रेसिंग का मेल आपके मेहमानों को प्रभावित करेगा।","4","1 कप",
["4 कप ब्रोकली (फूल, ब्लैंच करके ठंडे किए हुए)","1/3 कप कतले हुए बादाम","3/4 कप अंगूर (आधे कटे हुए)","1/4 कप लाल प्याज़ (पतला कटा हुआ)","2 बड़े चम्मच सेब का सिरका","2 बड़े चम्मच लाइट मेयोनेज़","1 बड़ा चम्मच डिजॉन सरसों","1 फाँक लहसुन (बारीक कटा हुआ)","1/8 छोटा चम्मच कोशर नमक","1/4 छोटा चम्मच काली मिर्च"],
["एक बड़े कटोरे में ब्लैंच करके ठंडे किए हुए ब्रोकली के फूल, बादाम, अंगूर, लाल प्याज़ और कटा हुआ ताज़ा अजमोदा मिलाएँ।","एक छोटे कटोरे में सेब का सिरका, लाइट मेयोनेज़, डिजॉन सरसों, बारीक कटा लहसुन, नमक और काली मिर्च को फेंटकर मिलाएँ।","ड्रेसिंग को सलाद पर डालें और धीरे से मिलाएँ ताकि वह समान रूप से लग जाए।"]))
r.append(R(6890310,"फूलगोभी फ्राइड \"राइस\"","बारीक कटी फूलगोभी बिना स्टार्च वाला शानदार साइड डिश हो सकती है, जिसमें चावल से कम कैलोरी और कार्बोहाइड्रेट होता है। या चिकन ब्रेस्ट, झींगा या टोफू डालकर इसे मुख्य व्यंजन बना लें। इस रेसिपी को और आसान बनाने के लिए, पैकेट वाली \"राइस जैसी कटी\" फूलगोभी से शुरू करें, जो कई किराना दुकानों में ताज़ी या फ्रोज़न मिलती है।","4","1/2 कप",
["1 बड़ा चम्मच जैतून का तेल (बाँटकर)","1 छोटा चम्मच तिल का तेल","3 डंठल हरा प्याज़ (स्प्रिंग ओनियन) (कटा हुआ)","1 1/2 बड़े चम्मच सोया सॉस (कम सोडियम वाला)","1/4 कप कम सोडियम वाला चिकन ब्रॉथ (बिना नमक मिलाए, वसा रहित)","1/8 छोटा चम्मच पिसी अदरक","2 बड़ी गाजर (बारीक कटी हुई)","3 कप फूलगोभी के फूल","1/8 छोटा चम्मच काली मिर्च (पिसी हुई)"],
["फूलगोभी को छोटे टुकड़ों में काटें और फ़ूड प्रोसेसर में चावल जैसी बनावट आने तक प्रोसेस करें, या फूलगोभी के गोले को ग्रेटर से कस लें; एक तरफ़ रख दें।","एक नॉनस्टिक पैन में मध्यम-तेज़ आँच पर 1/2 बड़ा चम्मच जैतून का तेल गरम करें। गाजर और हरा प्याज़ डालें और 5 मिनट भूनें।","पैन में बचा हुआ 1/2 बड़ा चम्मच जैतून का तेल और तिल का तेल डालें। फूलगोभी का \"राइस\" और बाकी सामग्री डालें और आँच मध्यम-धीमी कर दें। फूलगोभी के मिश्रण को बार-बार चलाते हुए 6-8 मिनट पकाएँ। फूलगोभी नरम होनी चाहिए, लेकिन गलकर लिजलिजी नहीं।"]))
r.append(R(6890316,"टमाटर और तुलसी के साथ ताज़ा मक्के का सलाद","यह ताज़ा गर्मियों का सलाद आपके समर कुकआउट के लिए एकदम सही है, और इसे आप सिर्फ़ 20 मिनट में तैयार कर सकते हैं। अगर आपके पास भुट्टा नहीं है, तो आप 2 कप फ्रोज़न मक्का भी इस्तेमाल कर सकते हैं।","4","3/4 कप",
["4 छोटे भुट्टे (रेशे और छिलके हटाए हुए)","3/4 कप ग्रेप टमाटर (आधे कटे हुए)","2 बड़े चम्मच ताज़ी तुलसी की पत्तियाँ (कटी हुई)","1/2 छोटा चम्मच नमक","2 बड़े चम्मच एक्स्ट्रा वर्जिन जैतून का तेल","1 बड़ा चम्मच सेब का सिरका"],
["एक बड़े सॉसपैन में तेज़ आँच पर पानी उबालें। भुट्टे डालें, आँच मध्यम करें और ढककर 8 मिनट पकाएँ, या जब तक काँटे से छेदने पर नरम-कुरकुरे न हो जाएँ। छलनी में पानी निथारें और जल्दी ठंडा करने के लिए ठंडे पानी के नीचे रखें।","इस बीच, बाकी सामग्री को एक मध्यम कटोरे में मिलाएँ। भुट्टे से दाने काटकर निकालें और टमाटर के मिश्रण में डालें। अच्छी तरह मिलने तक धीरे से मिलाएँ।"]))
r.append(R(6893480,"क्विनोआ ओटमील","ओटमील में क्विनोआ डालने से इस पारंपरिक नाश्ते में फ़ाइबर और प्रोटीन बढ़ जाता है। इस ओटमील की दोगुनी मात्रा बनाएँ और हफ़्ते के दिनों में त्वरित नाश्ते के लिए इसे एकल-सर्विंग हिस्सों में फ्रीज़ कर लें। बस इसे माइक्रोवेव में गरम करें।","4","2/3 कप ओटमील + 2 बड़े चम्मच रास्पबेरी + 1 बड़ा चम्मच बादाम",
["2 कप स्किम दूध","1/2 कप पानी","3/4 कप पुराने ज़माने के रोल्ड ओट्स","1/4 कप क्विनोआ","2 छोटे चम्मच शहद","1 छोटा चम्मच पिसी दालचीनी","1/2 छोटा चम्मच वनीला एक्सट्रैक्ट","1/8 छोटा चम्मच नमक","1/2 कप रास्पबेरी","1/4 कप कतले हुए बादाम (भुने हुए)"],
["एक बड़े सॉसपैन में दूध और पानी मिलाएँ और मध्यम आँच पर धीमी उबाल पर लाएँ।","ओट्स, क्विनोआ, शहद, दालचीनी, वनीला और नमक डालें। आँच धीमी कर दें।","ढककर बीच-बीच में चलाते हुए पकाएँ, जब तक ओट्स और क्विनोआ नरम न हो जाएँ, लगभग 15 मिनट। ऊपर से रास्पबेरी और बादाम डालकर परोसें।"]))
r.append(R(6893547,"ब्रेज़्ड सौंफ़ कंद और सफ़ेद बीन्स","संपूर्ण, आरामदायक भोजन के लिए इन ब्रेज़्ड बीन्स और सौंफ़ कंद को साइड में चिकन के साथ परोसें।","6","सौंफ़ कंद के 3 टुकड़े, 1/3 कप बीन्स और सॉस",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","2 मध्यम सौंफ़ कंद (हर एक ~11 औंस, डंठल और पत्तियाँ हटाए हुए, आठ भागों में कटे हुए)","1 मध्यम पीला प्याज़ (पतला कटा हुआ)","1 बड़ा चम्मच जैतून का तेल","1 कप कम सोडियम वाला चिकन ब्रॉथ (वसा रहित, कम सोडियम)","1/8 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","2 बड़े चम्मच रेड वाइन सिरका","15.5 औंस, 1 डिब्बा कैनेलिनी बीन्स (पानी निथारा और धोया हुआ)","1/4 कप अजमोदा (कटा हुआ)"],
["ओवन को 375°F पर पहले से गरम करें। 9x13 इंच की बेकिंग डिश पर कुकिंग स्प्रे लगाएँ।","तैयार बेकिंग डिश की तली में सौंफ़ कंद और प्याज़ को सजाकर रखें।","सौंफ़ कंद और प्याज़ पर जैतून का तेल, ब्रॉथ और सिरका डालें, और नमक व काली मिर्च से स्वाद दें।","1 घंटे तक बेक करें, बीच में एक बार चलाएँ।","बीन्स और अजमोदा मिलाएँ और 10 मिनट के लिए वापस ओवन में रखें।"]))
r.append(R(6893756,"पिज़्ज़ा डफ़ (पिज़्ज़ा का आटा)","शेफ़ का राज़: मैं आटा तैयार करने के लिए स्टील ब्लेड वाले अपने फ़ूड प्रोसेसर का इस्तेमाल करता हूँ। फ़ूड प्रोसेसर गूँधने का काम करता है। सफ़ेद साबुत गेहूँ का आटा ढूँढने की कोशिश करें, क्योंकि यह पारंपरिक लाल साबुत गेहूँ के आटे से रंग, बनावट और स्वाद में हल्का होता है। पानी का तापमान अपने मीट थर्मामीटर से मापें। यीस्ट के साथ काम करते समय, आटे के ठीक से फूलने के लिए पानी का तापमान बहुत महत्वपूर्ण होता है। सही तापमान 110–120ºF है।","12","1 टुकड़ा",
["1 1/2 कप मैदा (सर्व-उपयोगी आटा)","1 1/2 कप साबुत गेहूँ का आटा","1 पैकेट एक्टिव ड्राई यीस्ट","1 छोटा चम्मच नमक","1 कप पानी","1 छोटा चम्मच जैतून का तेल"],
["सभी सूखी सामग्री को अपने फ़ूड प्रोसेसर के कटोरे में डालें। अच्छी तरह मिलाने के लिए कुछ बार पल्स करें।","मशीन चलते हुए, 1 कप पानी धीमी और लगातार धार में डालें। आटे का गोला बनना चाहिए और वह फ़ूड प्रोसेसर के किनारे साफ़ कर देगा। अगर वह बहुत सूखा लगे, तो एक बार में 1 बड़ा चम्मच और पानी डालें। आटा तब सही होता है जब वह चिपचिपा न रहे और चिकना लगे। अगर वह बहुत चिपचिपा या गीला हो, तो आप एक बार में 1 बड़ा चम्मच और आटा डाल सकते हैं।","आटे को एक बड़े कटोरे में एक्स्ट्रा वर्जिन जैतून के तेल के साथ रखें। आटे को पलटें ताकि वह पूरी तरह तेल से ढक जाए, फिर प्लास्टिक रैप और कपड़े के तौलिये से कसकर ढक दें।","आटे को गरम जगह पर कम से कम 1 घंटे के लिए फूलने दें। फूलने के लिए अच्छी जगह है बंद ओवन, जिसमें ओवन की लाइट जली हो।","आटा दोगुना हो जाने के बाद, उसे दबाकर बैठा दें और जितनी देर हो सके, कम से कम 1 घंटे, फिर से फूलने दें। मैं हल्के आटे के लिए ज़्यादा देर फूलने देने का बड़ा प्रशंसक हूँ, ख़ासकर साबुत गेहूँ का आटा इस्तेमाल करते समय।"]))
r.append(R(6893898,"चिकन और खीरे के लेट्यूस रैप्स, पीनट सॉस के साथ","लेट्यूस रैप्स कम कार्बोहाइड्रेट वाला बढ़िया विकल्प हैं जो आपके भोजन में पोषक तत्व और स्वादिष्ट कुरकुरापन जोड़ते हैं। पीनट सॉस के साथ ये चिकन और खीरे के लेट्यूस रैप्स एक हल्का भोजन हैं जिन्हें बनाना और खाना मज़ेदार है।","4","2 रैप्स",
["1/4 कप कम वसा वाला पीनट बटर","2 बड़े चम्मच कम सोडियम वाला सोया सॉस","1 बड़ा चम्मच शहद","1 बड़ा चम्मच राइस विनेगर","1 छोटा चम्मच तिल का तेल","1 फाँक लहसुन (बारीक कटा हुआ)","1 छोटा चम्मच ताज़ा अदरक (कसा हुआ)","3 बड़े चम्मच पानी (या मनचाही गाढ़ाई पाने के लिए और)","2 साबुत बिना हड्डी और बिना त्वचा वाले चिकन ब्रेस्ट (पके हुए और कटे हुए)","1 बड़ा खीरा (जूलियन कटा हुआ (माचिस की तीलियों जितने पतले टुकड़ों में कटा हुआ))","1 बड़ी गाजर (जूलियन कटी हुई)","1/2 कप ताज़ा हरा धनिया (कटा हुआ)","8 सलाद पत्ते","2 डंठल हरा प्याज़ (स्प्रिंग ओनियन) (पतला कटा हुआ)","1 बड़ा चम्मच तिल (भुने हुए, सजाने के लिए)"],
["एक छोटे कटोरे में पीनट बटर, सोया सॉस, शहद, राइस विनेगर, तिल का तेल, बारीक कटा लहसुन और कसा हुआ अदरक फेंटकर मिलाएँ। मनचाही गाढ़ाई आने तक धीरे-धीरे पानी डालें।","बड़े सलाद पत्ते बिछाकर, हर पत्ते पर चिकन रखकर और ऊपर खीरा और गाजर डालकर लेट्यूस रैप्स तैयार करें।","चिकन पर पीनट सॉस डालें और ऊपर से हरा धनिया, हरा प्याज़ और तिल डालें।"]))
r.append(R(6893927,"रोस्टेड शिमला मिर्च और सफ़ेद बीन्स पर कॉड मछली","इस व्यंजन में मछली और बीन्स का इस्तेमाल होता है, दोनों स्वादिष्ट, कम वसा वाले प्रोटीन विकल्प हैं! अपना भोजन पूरा करने के लिए इसे हरे सलाद या भाप में पकी हरी फलियों के साथ परोसें।","4","1, 5 औंस मछली का फ़िलेट और 1 कप टमाटर, शिमला मिर्च और बीन्स का मिश्रण",
["4 साबुत मछली के फ़िलेट (जैसे कॉड, हर एक लगभग 5 औंस, थपथपाकर सुखाए हुए)","1/2 छोटा चम्मच पेपरिका","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","3 छोटे चम्मच एक्स्ट्रा वर्जिन जैतून का तेल (बाँटकर इस्तेमाल करें)","1 डिब्बा, 14.5 औंस डिब्बाबंद कटे हुए टमाटर, बिना नमक मिलाए","1 डिब्बा, 15 औंस डिब्बाबंद नेवी या ग्रेट नॉर्दर्न बीन्स (बिना नमक मिलाए, धोए और पानी निथारे हुए)","1/4 कप रोस्टेड लाल शिमला मिर्च (कटी हुई)","2 फाँक मध्यम लहसुन (बारीक कटा हुआ)","1/2 छोटा चम्मच ताज़ा (1 छोटा चम्मच सूखा) रोज़मेरी या स्वादानुसार (कटी हुई)"],
["एक छोटे कटोरे में पेपरिका, 1/4 छोटा चम्मच नमक और काली मिर्च मिलाएँ। फ़िलेट के दोनों तरफ़ पेपरिका का मिश्रण छिड़कें। एक बड़ी नॉनस्टिक कड़ाही में मध्यम आँच पर 1 छोटा चम्मच तेल गरम करें। फ़िलेट को 4 मिनट पकाएँ, पलटें, और बीच में अपारदर्शी होने तक 3 मिनट पकाएँ।","टमाटर को एक मध्यम सॉसपैन में रखें और मध्यम आँच पर बस उबलने तक गरम करें। बीन्स, लाल शिमला मिर्च, लहसुन, 2 छोटे चम्मच जैतून का तेल और रोज़मेरी डालें और गरम होने तक 1-2 मिनट पकाएँ। आँच से हटाएँ, ढक दें और मछली पकने तक रहने दें।","टमाटर, बीन्स और शिमला मिर्च के मिश्रण को 4 उथले कटोरों में बराबर बाँट दें और हर एक के ऊपर मछली का एक फ़िलेट रखें।"]))
r.append(R(6894160,"इंडियन सैल्मन स्टर फ्राई","इस स्टर फ्राई में मैंने पारंपरिक एशियाई स्वादों की जगह वैकल्पिक स्वाद दिए हैं। एशियाई स्वाद तेज़ और दमदार होते हैं, लेकिन कुछ बदलाव के लिए इस रेसिपी को आज़माएँ।","5","1 कप",
["1 बड़ा चम्मच वनस्पति तेल (बाँटकर इस्तेमाल करें)","2 छोटे चम्मच जीरा","1 छोटा चम्मच भूरी राई","1/2 छोटा चम्मच हल्दी","1 पाउंड सैल्मन फ़िलेट (बिना त्वचा के, 1 इंच के टुकड़ों में कटे हुए)","1 बड़ा प्याज़ (आधा काटकर, छीलकर, 1/2 इंच के टुकड़ों में कटा हुआ)","2 फाँक लहसुन (बारीक कटा हुआ)","1 बड़ा चम्मच ताज़ा अदरक (छीला हुआ, कसा हुआ)","1 छोटी तीखी हरी मिर्च (बारीक कटी हुई, वैकल्पिक)","1 कप चेरी टमाटर (आधे कटे हुए)"],
["एक कड़ाही या भारी तले वाले पैन में मध्यम-तेज़ आँच पर 2 छोटे चम्मच तेल गरम करें। जीरा, राई और हल्दी डालें और बीज चटकने तक 1 मिनट स्टर फ्राई करें। सैल्मन डालें और जल्दी लेकिन धीरे से लगभग 3-4 मिनट स्टर फ्राई करें। सैल्मन को पैन से निकालकर एक तरफ़ रख दें।","पैन में बचा हुआ तेल डालें। आँच मध्यम करें। प्याज़ डालें और प्याज़ के नरम होने तक लगभग 6-7 मिनट स्टर फ्राई करें। लहसुन, अदरक और हरी मिर्च डालें और 1 मिनट स्टर फ्राई करें। चेरी टमाटर डालें और चेरी टमाटर के बस नरम होने तक 1-2 मिनट स्टर फ्राई करें। सैल्मन को वापस डालें और बहुत धीरे से 1 मिनट स्टर फ्राई करें।"]))
r.append(R(6895022,"संतरा और एवोकाडो सलाद","चटक संतरा और मलाईदार एवोकाडो इस अनोखे, मधुमेह के अनुकूल सलाद में एक साथ आते हैं। साइड डिश के रूप में बेहतरीन, इसे त्वरित और आसान भोजन के लिए ग्रिल्ड चिकन ब्रेस्ट जैसे कम वसा वाले प्रोटीन के साथ परोसें।","4","1 कप",
["1 1/2 बड़े चम्मच एक्स्ट्रा वर्जिन जैतून का तेल","2 बड़े चम्मच नीबू का रस","1/2 छोटा चम्मच बिना मीठा सर्व-उपयोगी सिरप","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","3 बड़े संतरे (छिले और कटे हुए)","1 मध्यम एवोकाडो (कटा हुआ)","1 छोटा लाल प्याज़ (पतला कटा हुआ)","1/4 कप ताज़ा पुदीना (कटा हुआ)","1/4 कप लंबे कतले बादाम (भुने हुए)"],
["एक छोटे कटोरे में एक्स्ट्रा वर्जिन जैतून का तेल, नीबू का रस, बिना मीठा सर्व-उपयोगी सिरप, नमक और काली मिर्च को फेंटकर मिलाएँ।","एक थाली में संतरे, एवोकाडो, लाल प्याज़ और ताज़ा पुदीना सजाकर रखें।","ड्रेसिंग को सलाद पर डालें और ऊपर से भुने हुए लंबे कतले बादाम डालें।"]))
r.append(R(6895607,"ब्लैक बीन्स और पालक के साथ साउथवेस्ट ब्रेकफ़ास्ट टोस्टाडा","इन साउथवेस्ट ब्रेकफ़ास्ट टोस्टाडा में मसालेदार काले बीन्स, भुना हुआ पालक और एक अंडा परतों में लगाया गया है, जो आपके दिन की बढ़िया शुरुआत है। कुरकुरी मक्के की टॉर्टिला साबुत अनाज का आधार देती हैं, जबकि फ़ाइबर से भरपूर बीन्स और एवोकाडो से मिलने वाली सेहतमंद वसा रक्त शर्करा (ब्लड शुगर) के प्रबंधन में सहायता करती है। यह एक दमदार शाकाहारी नाश्ता है जो मधुमेह के अनुकूल भोजन योजना में अच्छी तरह फिट बैठता है।","4","प्रति सर्विंग 1 टोस्टाडा",
["4 छोटी मक्के की टॉर्टिला","1 कप बिना नमक मिलाए काले बीन्स (धोए और पानी निथारे हुए)","1 फाँक लहसुन (बारीक कटा हुआ)","1 बड़ा चम्मच पानी","1 छोटा चम्मच चिली पाउडर","1 छोटा चम्मच पिसा जीरा","2 छोटे चम्मच जैतून का तेल (बाँटकर)","4 कप ताज़ी पालक की पत्तियाँ","1/2 छोटा चम्मच नमक","4 बड़े अंडे","1 कप चेरी टमाटर (आधे कटे हुए)","1/2 साबुत एवोकाडो (कटा हुआ)","1 परत कुकिंग स्प्रे","सजाने के लिए हरे धनिये की पत्तियाँ"],
["ओवन को 400 डिग्री F पर पहले से गरम करें। मक्के की टॉर्टिला को चर्मपत्र कागज़ (पार्चमेंट पेपर) बिछी बेकिंग शीट पर रखें। दोनों तरफ़ हल्का सा कुकिंग स्प्रे करें। हर तरफ़ 6–7 मिनट या कुरकुरी और सुनहरी भूरी होने तक बेक करें। ओवन से निकालकर एक तरफ़ रख दें।","एक छोटे सॉसपैन में मध्यम आँच पर काले बीन्स, लहसुन की फाँक, पानी, चिली पाउडर, पिसा जीरा और नमक मिलाएँ।","2–3 मिनट तक गरम होने तक पकाएँ। काँटे या आलू मैशर से बीन्स को मसलकर फैलाने लायक गाढ़ापन बनाएँ। आँच से हटाकर एक तरफ़ रख दें।","एक बड़ी नॉनस्टिक कड़ाही में मध्यम आँच पर 1 छोटा चम्मच जैतून का तेल गरम करें। पालक और नमक डालें। बार-बार चलाते हुए मुरझाने तक, लगभग 2–3 मिनट पकाएँ। एक कटोरे में निकालकर एक तरफ़ रख दें।","उसी कड़ाही में मध्यम आँच पर बचा हुआ 1 छोटा चम्मच जैतून का तेल गरम करें। अंडों को कड़ाही में तोड़कर बराबर दूरी पर डालें। अंडों को अपनी पसंद के अनुसार पकाएँ (जैसे सनी साइड अप या ओवर ईज़ी)।","तैयार करने के लिए, हर बेक की हुई टॉर्टिला पर काले बीन्स के मिश्रण की समान परत फैलाएँ। ऊपर भुना हुआ पालक रखें, फिर पका हुआ अंडा और टमाटर। एवोकाडो के टुकड़े रखें और ऊपर से ताज़ी हरे धनिये की पत्तियाँ छिड़कें।"]))
r.append(R(6896958,"स्पार्कलिंग स्ट्रॉबेरी पुदीना पानी","सादे पानी के बजाय बुलबुलेदार, स्वादिष्ट पानी से अपनी प्यास बुझाएँ। सिर्फ़ 5 कैलोरी के साथ यह ताज़गी देने वाला और स्वादिष्ट है।","4","1 कप",
["3 1/2 कप स्पार्कलिंग वॉटर (बाँटकर)","2 छोटे चम्मच नीबू का रस","4 पत्तियाँ ताज़ा पुदीना (साथ में 4 पुदीने की टहनियाँ, बाँटकर)","4 बड़ी स्ट्रॉबेरी (डंठल हटाई हुई)"],
["स्ट्रॉबेरी, पुदीने की पत्तियाँ, नीबू का रस और 1/2 कप स्पार्कलिंग वॉटर को ब्लेंडर में धीमी गति पर चिकना होने तक, कम से कम 30 सेकंड, प्यूरी करें।","प्यूरी को परोसने वाले जग में डालें। बाकी स्पार्कलिंग वॉटर बहुत धीरे-धीरे डालें।","लंबे पेय ग्लासों में बर्फ़ के ऊपर ठंडा परोसें। हर एक को ताज़ा पुदीने की एक टहनी से सजाएँ।"]))
r.append(R(6897570,"मूँगफली","मूँगफली की पोषण संबंधी जानकारी","1","1 औंस",["1 औंस मूँगफली"],[]))
